// temporalDecoupling asks how often a loosely timed initiator synchronizes with the kernel.
func temporalDecoupling(ctx generator.GeneratorContext) generator.Problem {
	q := edakit.Pick([]int{100, 200, 250, 500, 1000})
	k := edakit.Int(5, 200)
	T := q * k
	if edakit.Int(0, 1) == 0 {
		ans := edakit.IntStr(k)
		stem := edakit.Sprintf("A loosely timed initiator uses temporal decoupling with a global quantum of %d ns: it runs ahead of the SystemC kernel and yields only when its local time offset reaches the quantum. How many times does it synchronize with the kernel over %d ns of simulated time?", q, T)
		return edakit.Choice(stem, ans,
			edakit.Sprintf("It yields once per quantum: %d / %d = %d synchronizations. A larger quantum means fewer context switches and more speed, but more timing error between initiators.", T, q, k),
			edakit.IntStr(k*2), edakit.IntStr(T), edakit.IntStr(k+1), edakit.IntStr(T/10))
	}
	q2 := q * edakit.Pick([]int{2, 4, 5, 10})
	ratio := q2 / q
	ans := edakit.IntStr(ratio)
	stem := edakit.Sprintf("An initiator synchronizes with the SystemC kernel once per quantum. The quantum is raised from %d ns to %d ns. By what factor does the number of synchronizations over a fixed simulated time fall?", q, q2)
	return edakit.Choice(stem, ans,
		edakit.Sprintf("Synchronizations are simulated time divided by the quantum, so they fall by %d / %d = %d. The worst-case timing skew between initiators grows to one quantum.", q2, q, ratio),
		edakit.Distinct(ratio, 3, ratio*ratio, q2-q, ratio+1)...)
}
